using System.Text.Json;

/// <summary>A compact view of recorded decisions and learning, not a second simulation.</summary>
internal static class CompanyTrialReport
{
    public static string Render(JsonElement payload, string viewer)
        => Template.Replace("__VIEWER__", System.Net.WebUtility.HtmlEncode(viewer))
            .Replace("__VIEWER_JSON__", JsonSerializer.Serialize(viewer + "/index.html"))
            .Replace("__DATA__", JsonSerializer.Serialize(payload).Replace("<", "\\u003c")
                .Replace(">", "\\u003e").Replace("&", "\\u0026"));

    private const string Template = """
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Under Glass · Company trial</title><link rel="stylesheet" href="__VIEWER__/ui.css"><script src="__VIEWER__/ui.js"></script>
<style>
main{max-width:1180px;margin:auto;padding:24px var(--page-gutter) 64px}nav{position:sticky;top:0;z-index:10;background:var(--bg);border-bottom:1px solid var(--line);padding:10px var(--page-gutter);display:flex;align-items:center;gap:20px}nav a{color:var(--ink)}nav button{margin-left:auto}button,select{box-shadow:none;border:1px solid var(--line)}h1{margin:8px 0}h2{margin:4px 0 14px}p{margin:8px 0 16px}.muted,small{color:var(--muted)}.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:24px 0 16px}.controls label{display:flex;gap:8px;align-items:center}.controls select{max-width:100%}.panel{border:1px solid var(--line);border-radius:var(--radius);padding:20px;margin:16px 0;background:var(--surface-hi)}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.row .spacer{flex:1}summary{cursor:pointer;list-style:none;display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:14px 0}summary::before{content:'▸';color:var(--muted)}details[open]>summary::before{content:'▾'}summary::-webkit-details-marker{display:none}.episode{border:1px solid var(--line);border-radius:10px;padding:0 16px;margin:10px 0}.episode>summary strong{flex:1}.badge{font:500 var(--step--1) var(--font-data);padding:4px 8px;border:1px solid currentColor;border-radius:7px;white-space:nowrap}.good{color:var(--like)}.bad{color:var(--dislike)}.waiting{color:var(--accent)}.rail{margin:10px 0 18px 8px;border-left:2px solid var(--line);padding-left:20px}.step{position:relative;padding:12px 0 16px;border-bottom:1px solid var(--line)}.step:last-child{border-bottom:0}.step::before{content:'';position:absolute;left:-26px;top:18px;width:10px;height:10px;border-radius:50%;background:var(--ink-2);outline:4px solid var(--surface-hi)}.step.good::before{background:var(--like)}.step.bad::before{background:var(--dislike)}.step.waiting::before{background:var(--accent)}.step .body{color:var(--ink)}.time{font:var(--step--1) var(--font-data);color:var(--muted)}.detail{margin-top:8px;padding:0 12px;background:var(--surface);border:1px solid var(--line);border-radius:8px}.detail summary{padding:10px 0}.detail p{font-size:var(--step--1)}.table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums;margin:12px 0}.table th{text-align:left;font-weight:500;color:var(--muted)}.table td,.table th{padding:9px 6px;border-bottom:1px solid var(--line)}.bar{height:4px;background:var(--surface-2);max-width:180px;margin-top:6px}.bar span{display:block;height:100%;background:var(--like)}pre{max-height:360px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:12px var(--font-data)}.legend{display:flex;flex-wrap:wrap;gap:14px;font-size:var(--step--1)}.changes{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.comparison{margin:10px 0;padding:0 12px;border:1px solid var(--line);border-radius:8px}a{color:var(--like)}.empty{padding:24px 0;color:var(--muted)}blockquote{border-left:3px solid var(--like);padding-left:12px;margin:8px 0 12px}a:focus-visible,summary:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:620px){main{padding-top:18px}.panel{padding:14px}.controls{display:block}.controls label{margin:12px 0}.episode>summary .time{width:100%}.table td,.table th{font-size:12px}.badge{white-space:normal}.metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style></head><body>
<nav><a href="__VIEWER__/tools.html">Under Glass / Tools</a><a href="summary.json">Summary</a><button class="theme led" data-theme-toggle aria-pressed="false">Dark mode</button></nav>
<main><span class="label">Offline experiment · actual recordings</span><h1>From memory to shared time</h1><p class="muted">Follow an offer through its answer, activity and learning. Select one episode to open its chain.</p>
<div class="controls"><label>Recording <select id="run"></select></label><label>Ending <select id="ending"><option value="">All endings</option></select></label></div>
<dl class="metric-grid" id="metrics"></dl>
<section class="panel"><div class="row"><h2 id="runTitle"></h2><span class="spacer"></span><a id="viewer">Open Run Viewer →</a><a id="raw">JSON</a></div><p class="muted" id="method"></p>
<div class="legend"><span class="good">● Completed</span><span class="bad">● Declined / interrupted / missed</span><span class="waiting">● Seeking / waiting</span></div>
<div id="episodes"></div><details class="detail"><summary>What is private, and what was witnessed?</summary><p>This page reads private company and memory receipts. A thought, remembered reason or expected chance is known only to that holder. Run Viewer shows ordinary recorded acts and their perceived accounts. Starting a game is not proof that it finished. Missed searches reveal no destination, rejection or hidden motive.</p><p>Immediate games only: no future appointments, full Lives observer 0.2 integration, canon history pack or model calls.</p></details></section>
<section class="panel"><h2>The same choice without a history</h2><p class="muted">Recorded options, state and draw held fixed. Open a comparison to inspect the effect.</p><div id="comparisons"></div></section>
<details class="panel"><summary>Matrix and limits</summary><p id="matrix"></p><p>All seeds are included. Fictional fixtures use equal yes/no weights with state-weighted not-now to exercise branches and large seeking weights to make missing searches inspectable. These are mechanism probes, not recommended tuning. The normal town starts without a history pack and learns only from its own run.</p><p>Completed games currently give each participant the catalog joy scaled by sensitivity. Future plans, richer interpretations and subjective disappointment remain later work. Quiet runs are retained.</p><a href="synthetic-history.json">Inspect synthetic history</a></details>
<noscript>Enable JavaScript or open summary.json and the recordings directly.</noscript></main>
<script type="application/json" id="data">__DATA__</script>
<script>
'use strict';
const data=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),viewerPath=__VIEWER_JSON__;
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
const time=m=>'Day '+(Math.floor(m/1440)+1)+' · '+String(Math.floor(m%1440/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');
const pct=n=>(n*100).toFixed(1)+'%',color=s=>s==='Completed'?'good':['Refused','Interrupted','NotFound','Unavailable','Aborted'].includes(s)?'bad':'waiting';
const plain={Seeking:'Looking for company',Searching:'Looking around',Pending:'Waiting for an answer',Playing:'Playing together',Completed:'Completed',Interrupted:'Interrupted',NotFound:'Not found',Unavailable:'Unavailable',NotNow:'Not now',Refused:'Declined',Aborted:'Stopped looking'};
function link(run,at=0,person=''){const u=new URL(viewerPath,location.href);u.searchParams.set('run',new URL(run.file,location.href));u.hash='t='+at+'&person='+encodeURIComponent(person)+'&tab=inner';return u.href}
function disclosure(title,child){const d=el('details',undefined,'detail');d.append(el('summary',title),child);return d}
function raw(value){return el('pre',JSON.stringify(value,null,2))}
function table(headers){const t=el('table',undefined,'table'),head=el('thead'),tr=el('tr');headers.forEach(h=>tr.append(el('th',h)));head.append(tr);t.append(head,el('tbody'));return t}
function numberCell(value){const td=el('td',pct(value)),bar=el('div',undefined,'bar'),fill=el('span');fill.style.width=(value*100)+'%';bar.append(fill);td.append(bar);return td}
function choiceCard(row){const card=el('div'),d=row.decision;card.append(el('strong',d.alternatives.find(a=>a.option.id===d.selectedId)?.option.line||'Continue with the existing routine.'));const t=table(['Option','Recorded chance']);for(const a of d.alternatives){const tr=el('tr');tr.append(el('td',a.option.line),numberCell(a.probability));t.tBodies[0].append(tr)}card.append(t);const memories=el('div');for(const item of d.recall.items){memories.append(el('blockquote',item.text),el('small',item.preRun?'Before the run':'Learned during this run'))}card.append(disclosure('Memories that came to mind',memories),disclosure('Decision receipt',raw(row)));return card}
function learnLabel(key){if(key.kind==='Answers')return 'Chance of a yes';if(key.kind==='Availability')return 'Chance they are available';if(key.kind==='Activity')return 'Chance the game completes';return 'Chance of finding them here'}
function episodeCard(run,updates){const last=updates.at(-1),e=last.episode,d=el('details',undefined,'episode'),s=el('summary');s.append(el('strong',e.asker+' → '+e.asked),el('span',time(e.startedAt),'time'),el('span',plain[e.stage]||e.stage,'badge '+color(e.stage)));d.append(s);d.addEventListener('toggle',()=>{if(!d.open||d.dataset.loaded)return;d.dataset.loaded='1';const rail=el('div',undefined,'rail');const rows=updates.map(u=>({at:u.at,order:0,kind:'update',data:u}));run.choices.filter(c=>c.episodeId===e.id).forEach(c=>rows.push({at:c.decision.opportunity.at,order:1,kind:'choice',data:c}));run.answers.filter(a=>a.episodeId===e.id).forEach(a=>rows.push({at:a.at,order:2,kind:'answer',data:a}));run.learning.filter(l=>l.causeId.startsWith('company:'+e.id+':')).forEach(l=>rows.push({at:l.at,order:3,kind:'learn',data:l}));rows.sort((a,b)=>a.at-b.at||a.order-b.order);for(const r of rows){const item=el('div',undefined,'step'),body=el('div',undefined,'body');item.append(el('div',time(r.at),'time'));if(r.kind==='update'){const u=r.data;item.classList.add(color(u.episode.stage));body.append(el('strong',plain[u.episode.stage]||u.episode.stage),el('p',u.reason,'muted'))}else if(r.kind==='choice'){body.append(el('div',r.data.phase==='seek'?'Choice · where to look':'Choice · whether to ask','label'),choiceCard(r.data))}else if(r.kind==='answer'){const a=r.data;body.append(el('strong',a.holder+' · '+a.options.find(o=>o.id===a.selectedId).line));const odds=table(['Answer','Recorded chance']);for(const option of a.options){const tr=el('tr');tr.append(el('td',option.line),numberCell(option.probability));odds.tBodies[0].append(tr)}body.append(disclosure('Other possible answers',odds))}else{const l=r.data;body.append(el('strong',l.holder+' learned'));const changes=el('div',undefined,'changes');for(const x of l.expectations){changes.append(el('span',learnLabel(x.key)+' '+pct(x.before)+' → '+pct(x.after),'badge '+(x.after<x.before?'bad':'good')))}for(const a of l.associations){changes.append(el('span',a.object.kind+' · '+a.object.key+' '+(a.amount>=0?'+':'')+a.amount.toFixed(3),'badge '+(a.amount>=0?'good':'bad')))}body.append(changes,disclosure('Learning receipt',raw(l)))}item.append(body);rail.append(item)}d.append(rail);const a=el('a','Open this moment in Run Viewer →');a.href=link(run,e.startedAt,e.asker);d.append(a,el('p','Private receipts above; ordinary act knowledge is recorded separately.','muted'))});return d}
function comparisonCard(row){const pair=row.comparison,d=el('details',undefined,'comparison'),s=el('summary');s.append(el('strong',time(row.decision.opportunity.at)+' · '+row.decision.opportunity.holder+' · '+row.phase),el('span',!pair.comparable?'Eligibility changed':pair.selectionChanged?'Different choice':pair.probabilitiesChanged?'Different odds':'Same odds','badge '+(!pair.comparable?'waiting':pair.selectionChanged?'good':'')));d.append(s);d.addEventListener('toggle',()=>{if(!d.open||d.dataset.loaded)return;d.dataset.loaded='1';if(!pair.comparable){d.append(el('p','Removing this history changed which options were available. This is not a matched probability comparison.','muted'),disclosure('Inspect the eligibility change',raw(pair)));return}const before=pair.withHistory,after=pair.withoutHistory,t=table(['Option','With history','Without reading','Change']);for(const a of before.alternatives){const b=after.alternatives.find(b=>b.option.id===a.option.id);const tr=el('tr');tr.append(el('td',a.option.line),numberCell(a.probability),numberCell(b.probability),el('td',((b.probability-a.probability)*100).toFixed(1)+' pp'));t.tBodies[0].append(tr)}const label=(d)=>d.alternatives.find(a=>a.option.id===d.selectedId)?.option.line||'Existing routine';d.append(el('p','Actual: '+label(before)),el('p','Without the reading: '+label(after)),t,el('small','Same recorded draw: '+before.unit+' · Removed: '+pair.removedHistoryIds.join(', ')),disclosure('Recorded reasons and comparison',raw(pair)))});return d}
function render(){const run=data.runs[Number($('run').value)],ending=$('ending').value;$('runTitle').textContent=run.label+' · seed '+run.count.seed;$('method').textContent=run.method;$('viewer').href=link(run);$('raw').href=run.file;$('metrics').replaceChildren();for(const [value,label] of [[run.count.episodes,'episodes'],[run.count.completed,'completed'],[run.count.comparable,'matched choices'],[run.count.changedSelection,'different selections']]){const cell=el('div',undefined,'metric'),dd=el('dd');dd.append(el('strong',String(value),'metric-value'));cell.append(el('dt',label),dd);$('metrics').append(cell)}const grouped=new Map();for(const u of run.updates){if(!grouped.has(u.episode.id))grouped.set(u.episode.id,[]);grouped.get(u.episode.id).push(u)}const groups=[...grouped.values()].filter(g=>!ending||g.at(-1).episode.stage===ending);$('episodes').replaceChildren(...groups.map(g=>episodeCard(run,g)));if(!groups.length)$('episodes').append(el('p',run.updates.length?'No episodes match this ending.':'No company episodes occurred in this fixed run. The quiet result is retained.','empty'));const pairs=run.choices.filter(c=>c.comparison);$('comparisons').replaceChildren(...pairs.map(comparisonCard));if(!pairs.length)$('comparisons').append(el('p','No starting history was removed in this recording. Inspect the synthetic household runs for controlled comparisons.','muted'));}
data.runs.forEach((run,i)=>{const option=el('option',(run.group==='town'?'Town':'Synthetic')+' · '+run.label+' · seed '+run.count.seed);option.value=String(i);$('run').append(option)});for(const value of Object.keys(plain)){const option=el('option',plain[value]);option.value=value;$('ending').append(option)}$('matrix').textContent=data.summary.method;$('run').addEventListener('change',render);$('ending').addEventListener('change',render);render();
</script></body></html>
""";
}
